CREATE TABLE geo_risk_version (version_id UUID PRIMARY KEY, status VARCHAR(20) NOT NULL, effective_from TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, approved_by VARCHAR(100), change_reason VARCHAR(500) NOT NULL, checksum VARCHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL, activated_at TIMESTAMPTZ);
CREATE TABLE geo_risk_index_row (row_id UUID PRIMARY KEY, version_id UUID NOT NULL REFERENCES geo_risk_version(version_id), province VARCHAR(100) NOT NULL, region VARCHAR(100), urban_tier_geo VARCHAR(30), traffic_density_score DOUBLE PRECISION NOT NULL, vehicle_theft_risk_score DOUBLE PRECISION NOT NULL, accident_frequency_index DOUBLE PRECISION NOT NULL, flood_risk_score DOUBLE PRECISION NOT NULL, storm_risk_score DOUBLE PRECISION NOT NULL, fire_risk_score DOUBLE PRECISION NOT NULL, crime_risk_score DOUBLE PRECISION NOT NULL, healthcare_access_score DOUBLE PRECISION NOT NULL, hospital_cost_index DOUBLE PRECISION NOT NULL, repair_cost_index DOUBLE PRECISION NOT NULL, construction_cost_index DOUBLE PRECISION NOT NULL);
CREATE UNIQUE INDEX uq_geo_risk_version_province ON geo_risk_index_row(version_id, province);
CREATE TABLE cost_index_version (version_id UUID PRIMARY KEY, status VARCHAR(20) NOT NULL, effective_from TIMESTAMPTZ NOT NULL, created_by VARCHAR(100) NOT NULL, approved_by VARCHAR(100), change_reason VARCHAR(500) NOT NULL, checksum VARCHAR(64) NOT NULL, created_at TIMESTAMPTZ NOT NULL, activated_at TIMESTAMPTZ);
CREATE TABLE cost_index_row (row_id UUID PRIMARY KEY, version_id UUID NOT NULL REFERENCES cost_index_version(version_id), year INTEGER NOT NULL, month INTEGER NOT NULL, month_start DATE NOT NULL, medical_inflation_index DOUBLE PRECISION NOT NULL, vehicle_repair_inflation_index DOUBLE PRECISION NOT NULL, construction_inflation_index DOUBLE PRECISION NOT NULL, travel_medical_cost_index DOUBLE PRECISION NOT NULL, general_expense_index DOUBLE PRECISION NOT NULL);
CREATE UNIQUE INDEX uq_cost_index_version_month ON cost_index_row(version_id, month_start);
